import {
  Border,
  Box,
  Button,
  CustomSpooder,
  Stack,
  TextInput,
  TypeFace,
  useTheme,
} from "@greysole/spooder-component-library";
import WireframeSphere from "./background/WireframeSphere";
import { useState } from "react";
import { login } from "./Request";

export default function App() {
  const { themeColors } = useTheme();
  const urlReason = new URLSearchParams(window.location.search).get("reason");
  const nextUrl = new URLSearchParams(window.location.search).get("next");
  const [username, setUsername] = useState<string>("");
  const [password, setPassword] = useState<string>("");
  const [reason, setReason] = useState<string>(urlReason ?? "");
  return (
    <Box
      width="100vw"
      height="100dvh"
      alignItems="center"
      justifyContent="center"
    >
      <Box className="login-box">
        <Border>
          <Stack spacing="medium" align="center" padding="medium">
            <CustomSpooder />
            {reason ? <TypeFace>{reason}</TypeFace> : null}
            <TypeFace>Login to this Spooder</TypeFace>
            <TextInput
              value={username}
              onInput={setUsername}
              placeholder="Username"
            />
            <TextInput
              value={password}
              onInput={setPassword}
              placeholder="Password"
              password
            />
            <Button
              label="Login"
              onClick={() => {
                login({ username, password })
                  .then((data) => {
                    if (data.status === "active") {
                      window.location.href = nextUrl ?? "/mod";
                    } else if (data.status === "nolocal") {
                      setPassword("");
                      setReason("Lol, you are not a local user");
                    } else if (data.status === "temporary") {
                      setPassword("");
                      setReason(
                        "That's a temporary password. Put in a new one and I'll log you in."
                      );
                    } else if (data.status === "badpassword") {
                      setPassword("");
                      setReason("Wrong password. Try again.");
                    }
                  })
                  .catch((e) => {
                    console.error("ERROR", e);
                  });
              }}
            />
          </Stack>
        </Border>
      </Box>

      <WireframeSphere
        startColor={Number(themeColors.colorAnalogousCW.replace("#", "0x"))}
        endColor={Number(themeColors.colorAnalogousCCW.replace("#", "0x"))}
      />
    </Box>
  );
}
